<?php require 'config.php'; role_required(['admin','storekeeper','procurement','director']); ensure_app_schema(); $pdo=db(); $from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');
if(isset($_GET['csv'])){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename=material-report.csv');echo "\xEF\xBB\xBFวันที่,เลขที่คำขอ,แผนก,สถานะ\n"; $s=$pdo->prepare("SELECT request_no,department,status,created_at FROM requests WHERE DATE(created_at) BETWEEN ? AND ? ORDER BY id DESC");$s->execute([$from,$to]);foreach($s as $r)echo date('d/m/Y',strtotime($r['created_at'])).",".$r['request_no'].",".$r['department'].",".$r['status']."\n";exit;}
$dept=$pdo->query("SELECT department,COUNT(*) total FROM requests GROUP BY department ORDER BY total DESC")->fetchAll();$low=$pdo->query("SELECT * FROM materials WHERE stock<min_stock ORDER BY stock ASC")->fetchAll();
?><!doctype html><html lang="th"><head><?php include 'partials/head.php';?><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body><?php include 'partials/nav.php';?><main class="container"><h2>รายงาน</h2><div class="panel"><form method="get" class="row"><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button>ค้นหา</button><a class="button" href="reports.php?from=<?=e($from)?>&to=<?=e($to)?>&csv=1">Export CSV</a></form></div><div class="panel"><h3>คำขอแยกตามแผนก (ข้อมูลจริง)</h3><canvas id="deptChart"></canvas></div><div class="panel"><h3>พัสดุใกล้หมด</h3><table class="table"><tr><th>รหัส</th><th>ชื่อ</th><th>ยอดคงเหลือ</th><th>ขั้นต่ำ</th></tr><?php foreach($low as $m):?><tr><td><?=e($m['code'])?></td><td><?=e($m['name'])?></td><td><?=fmt_num($m['stock'])?></td><td><?=fmt_num($m['min_stock'])?></td></tr><?php endforeach;?></table></div></main></div></div><script>new Chart(document.getElementById('deptChart'),{type:'bar',data:{labels:<?=json_encode(array_column($dept,'department'),JSON_UNESCAPED_UNICODE)?>,datasets:[{label:'จำนวนคำขอ',data:<?=json_encode(array_map('intval',array_column($dept,'total')))?>,backgroundColor:'#b48a6a'}]},options:{responsive:true}})</script></body></html>
